export function minesweeperNumbers(board) {
    const rows = board.length, cols = rows ? board[0].length : 0;
    return board.map((line, r) => [...line].map((c, col) => {
        if (c === '*')
            return '*';
        let count = 0;
        for (let dr = -1; dr <= 1; dr++)
            for (let dc = -1; dc <= 1; dc++) {
                if (!dr && !dc)
                    continue;
                const rr = r + dr, cc = col + dc;
                if (rr >= 0 && cc >= 0 && rr < rows && cc < cols && board[rr][cc] === '*')
                    count++;
            }
        return String(count);
    }).join(''));
}
